   59  async function withTimeout<T>(
   60    fn: () => Promise<T>,
   61    path: string,
   62    opts: SafeFsOptions,
   63  ): Promise<T> {
   64    const t = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
   65    if (t <= 0 || process.platform !== 'win32') return fn();
   66  
   67    let timer: NodeJS.Timeout | undefined;
   68    const timeoutP = new Promise<never>((_, reject) => {
   69      timer = setTimeout(() => {
   70        reject(new OSAccessError(buildAVTimeoutError(path, t)));
   71      }, t);
   72      timer.unref?.();
   73    });
   74  
   75    try {
   76      return await Promise.race([fn(), timeoutP]);
   77    } finally {
   78      if (timer) clearTimeout(timer);
   79    }
   80  }
   81  
   82  async function wrap<T>(
   83    fn: () => Promise<T>,
   84    path: string,
   85    opts: SafeFsOptions = {},
   86  ): Promise<T> {
   87    try {
   88      return await withTimeout(fn, path, opts);
   89    } catch (rawErr) {
   90      if (rawErr instanceof OSAccessError) throw rawErr;
   91      const osErr = classifyFsError(rawErr, path);
   92      if (osErr) throw new OSAccessError(osErr);
   93      throw rawErr;
   94    }
