 1632  		const resolvedTargetCwd = resolvePath(targetCwd);
 1633  		const sourceEntries = loadEntriesFromFile(resolvedSourcePath);
 1634  		if (sourceEntries.length === 0) {
 1635  			throw new Error(`Cannot fork: source session file is empty or invalid: ${resolvedSourcePath}`);
 1636  		}
 1637  
 1638  		const sourceHeader = sourceEntries.find((e) => e.type === "session") as SessionHeader | undefined;
 1639  		if (!sourceHeader) {
 1640  			throw new Error(`Cannot fork: source session has no header: ${resolvedSourcePath}`);
 1641  		}
 1642  
 1643  		const dir = sessionDir ? normalizePath(sessionDir) : getDefaultSessionDir(resolvedTargetCwd);
 1644  		if (!existsSync(dir)) {
 1645  			mkdirSync(dir, { recursive: true });
 1646  		}
 1647  
