 1649  		if (options?.id !== undefined) {
 1650  			assertValidSessionId(options.id);
 1651  		}
 1652  		const newSessionId = options?.id ?? createSessionId();
 1653  		const timestamp = new Date().toISOString();
 1654  		const fileTimestamp = timestamp.replace(/[:.]/g, "-");
 1655  		const newSessionFile = join(dir, `${fileTimestamp}_${newSessionId}.jsonl`);
 1656  
 1657  		// Write new header pointing to source as parent, with updated cwd
 1658  		const newHeader: SessionHeader = {
 1659  			type: "session",
 1660  			version: CURRENT_SESSION_VERSION,
 1661  			id: newSessionId,
 1662  			timestamp,
 1663  			cwd: resolvedTargetCwd,
