 1066  async function persistChildRuntimeEvent(runtime: ForkRuntimeState, event: StreamEvent): Promise<void> {
 1067    if (event.type !== StreamEvents.PERSIST_MESSAGE) return;
 1068    const payload = (event.payload ?? {}) as Record<string, unknown>;
 1069    // subagent_run_id is correct for the parent thread projection, where subagent
 1070    // messages must not re-enter the parent LLM history. In the child sidechain
 1071    // the same persisted assistant turn is local history, so store it without
 1072    // the parent-thread exclusion marker.
 1073    const { subagent_run_id: _parentSubagentRunId, ...childPayload } = payload;
 1074    try {
 1075      await runtime.childStorage.appendStreamEvent({
 1076        ...event,
 1077        payload: childPayload,
 1078      });
 1079    } catch {
 1080      // 子 sidechain 是 resume 的本地历史副本；写入失败不应阻断父线程主事件流。
