   85  export function computePartialKeepLastN(params: {
   86    messages: Message[];
   87    systemPrompt: string;
   88    tools?: ToolParam[];
   89    contextWindowTokens: number;
   90    targetAfterCompact: number;
   91    estimator?: TokenEstimator;
   92  }): number {
   93    const { messages, systemPrompt, tools, contextWindowTokens, targetAfterCompact, estimator } = params;
   94  
   95    const fullTarget = Math.floor(contextWindowTokens * targetAfterCompact);
   96    const messagesTarget = computeMessagesTargetFromFullTarget(
   97      fullTarget,
   98      systemPrompt,
   99      tools,
  100      estimator,
  101    );
  102    const tailBudget = messagesTarget - SUMMARY_OUTPUT_RESERVE_TOKENS;
  103    if (tailBudget <= 0) return NORMAL_MIN_KEEP_LAST_N;
  104  
  105    let accumulated = 0;
  106    let keep = 0;
  107    for (let i = messages.length - 1; i >= 0; i--) {
  108      const tokens = estimateTokens([messages[i]], estimator);
  109      if (accumulated + tokens > tailBudget) break;
  110      accumulated += tokens;
  111      keep++;
  112    }
  113  
  114    // 保证头部至少留 MIN_MESSAGES_TO_SUMMARIZE 条可摘——否则压缩空转
  115    // （compactConversation 对 messages.length <= keepLastN + 1 直接 no-op）。
  116    const maxKeep = Math.max(NORMAL_MIN_KEEP_LAST_N, messages.length - MIN_MESSAGES_TO_SUMMARIZE);
  117    return Math.min(Math.max(NORMAL_MIN_KEEP_LAST_N, keep), maxKeep);
  118  }
